const MACHINE_FRAGMENT="// Projector light, light theme (ink on paper).\n// uPass 0: the beam between the lens and the screen, and the light it lays on the screen.\n// uPass 1: the lamp seen through the round window of the lamp house.\nuniform float uPass;\nuniform float uLamp;   // lamp energy 0..1 (rides an envelope in JS)\nuniform float uBeam;   // shutter open 0..1\nuniform vec3 uLens;    // lens front centre (world)\nuniform float uLensR;\nuniform vec4 uScreen;  // picture x0, x1, z0, z1\nuniform float uScreenY;\nuniform vec4 uWin;     // lamp window: glass plane x, centre y and z, radius\n\nvec4 inkFor(vec3 seen, float cover){\n  vec3 absorbed = 1. - seen;\n  float a = max(max(absorbed.r, max(absorbed.g, absorbed.b)), cover);\n  return vec4(vec3(a) - absorbed, a);\n}\nvec4 over(vec4 top, vec4 under){ return top + under * (1. - top.a); }\n\nuniform vec3 uBeamInk;  // projector light as seen on paper\nuniform vec3 uLampBody; // lamp body\nuniform vec3 uLampCore; // pale core\n#define BEAM uBeamInk\n#define BODY uLampBody\n#define CORE uLampCore\n\nvec4 beam(vec2 vb){\n  vec3 V = towardViewer();\n  vec3 p0 = rayOf(vb);\n  float yA = uLens.y, yB = uScreenY + .2;\n  float tA = (yA - p0.y) / V.y;\n  float tB = (yB - p0.y) / V.y;\n  float t0 = min(tA, tB), t1 = max(tA, tB);\n  vec3 cB = vec3((uScreen.x + uScreen.y) * .5, yB, (uScreen.z + uScreen.w) * .5);\n  vec2 hB = vec2((uScreen.y - uScreen.x) * .5, (uScreen.w - uScreen.z) * .5);\n  float e = 0.;\n  float dust = 0.;\n  const int N = 40;\n  float dt = (t1 - t0) / float(N);\n  float j = hash12(gl_FragCoord.xy);\n  for (int i = 0; i < N; i++) {\n    float t = t0 + (float(i) + j) * dt;\n    vec3 p = p0 + t * V;\n    float s = clamp((yA - p.y) / (yA - yB), 0., 1.);\n    vec3 c = mix(uLens, cB, s);\n    vec2 h = mix(vec2(uLensR), hB, s);\n    vec2 q = abs(vec2(p.x - c.x, p.z - c.z)) - h;\n    float edge = max(q.x, q.y);\n    float soft = mix(.35, 1.2, s);\n    float inside = 1. - smoothstep(-soft, soft * .4, edge);\n    // light spreads: energy per area falls with the cross-section, the near end is brightest\n    float spread = (uLensR * uLensR) / (h.x * h.y);\n    float fall = mix(1., .18, smoothstep(0., 1., s)) + .5 * spread;\n    float n = fbm3(p * .06 + vec3(0., uTime * .35, uTime * .12));\n    // fade the near end in from the lens face so the beam never starts on a hard cut\n    float born = smoothstep(0., .05, s);\n    float w = inside * born * fall * dt;\n    e += w;\n    dust += w * smoothstep(.55, .85, n);\n  }\n  e *= .03;\n  dust *= .03;\n  float m = 1. - exp(-1.6 * (e + .8 * dust));\n  // light laid on the screen picture area\n  vec3 ps = onWallY(vb, uScreenY + .05);\n  float px = pixelOf() / uCam.w;\n  float onPic = window(ps.x, uScreen.x, uScreen.y, .7 * px) * window(ps.z, uScreen.z, uScreen.w, .7 * px);\n  float wash = .16 * onPic;\n  vec3 seen = mix(vec3(1.), BEAM, clamp(.62 * m + wash, 0., 1.));\n  vec4 ink = inkFor(seen, 0.);\n  return ink * uBeam * uLamp;\n}\n\nvec4 lamp(vec2 vb){\n  vec3 p = onWallX(vb, uWin.x);\n  float r = length(vec2(p.y - uWin.y, p.z - uWin.z));\n  float px = pixelOf() / uCam.w;\n  // ink ends at the inner edge of the window's outline stroke\n  float glass = 1. - smoothstep(uWin.w - .3 / uK - .7 * px, uWin.w - .3 / uK, r);\n  float x = r / uWin.w;\n  float energy = uLamp * (exp(-x * x * 3.2) * 1.2 + .35);\n  float m = 1. - exp(-2.2 * energy);\n  vec3 seen = mix(vec3(1.), BODY, smoothstep(.05, .55, m));\n  seen = mix(seen, CORE, smoothstep(.62, .92, m) * exp(-x * x * 5.));\n  float cover = .86 * smoothstep(.45, .9, m);\n  vec4 ink = inkFor(seen, cover);\n  return ink * glass * smoothstep(0., .25, uLamp);\n}\n\nvoid main(){\n  vec2 vb = viewOf(gl_FragCoord.xy);\n  vec4 c = uPass < .5 ? beam(vb) : lamp(vb);\n  c.rgb = min(c.rgb, vec3(c.a));\n  float d = (hash12(gl_FragCoord.xy + 7.) - .5) / 255. * smoothstep(0., 1.5 / 255., c.a);\n  gl_FragColor = clamp(c + d, 0., 1.);\n}\n";
